import { Tooltip } from "@/components/ui/Tooltip";
import { StatusLegend } from "./StatusLegend";
import styles from "./history.module.css";
export function StatusBadge({
  status,
  deliveryState,
  error,
  dispatchedAt,
}: {
  status: string;
  deliveryState: string;
  error: string | null;
  dispatchedAt: Date | null;
}) {
  const review = deliveryState === "UNCERTAIN";
  const label = review
    ? "Needs review"
    : ({
        SENT: "Sent",
        REPLIED: "Replied",
        QUEUED: "Queued",
        FAILED: "Failed",
        CANCELLED: "Cancelled",
      }[status] ?? status);
  const color = review
    ? "var(--h-yellow)"
    : ({
        SENT: "var(--h-green)",
        REPLIED: "var(--appearance-replied, var(--h-pink))",
        QUEUED: "var(--appearance-queued, var(--h-purple))",
        FAILED: "var(--destructive)",
        CANCELLED: "var(--h-muted)",
      }[status] ?? "var(--h-muted)");
  const background = review
    ? "var(--color-statusbadge-detail-1)"
    : ({
        SENT: "var(--appearance-sent-bg, var(--color-statusbadge-detail-2))",
        REPLIED:
          "var(--appearance-replied-bg, var(--color-statusbadge-detail-3))",
        QUEUED:
          "var(--appearance-queued-bg, var(--color-statusbadge-detail-4))",
        FAILED: "var(--color-statusbadge-detail-5)",
      }[status] ?? "var(--h-inset)");
  return (
    <Tooltip
      className="history-surface"
      content={
        <div className="space-y-2">
          <StatusLegend />
          {error && <p className="text-body">{error}</p>}
          {status === "QUEUED" && !dispatchedAt && (
            <p className="text-body">Waiting for delivery service</p>
          )}
        </div>
      }
    >
      <span
        tabIndex={0}
        className={`${styles.badge} inline-flex items-center gap-[7px] rounded-full py-1 px-3 text-[12.5px] font-bold cursor-help`}
        style={{ color, background }}
      >
        <span
          className="w-1.5 h-1.5 shrink-0 rounded-[50%] [background:currentColor]"
          aria-hidden="true"
        />
        {label}
      </span>
    </Tooltip>
  );
}
